test('final grade equals 20 percent of homework average plus 30 percent of quiz average plus 50 percent of exam', function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] }), {
    homeworkAverage: 90,
    quizAverage: 75,
    examScore: 60,
    final: 70.5,
    display: '70.5',
    droppedHomework: 70
  });
});

test('fewer than four homework scores are all averaged and the lowest is not dropped', function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] }), {
    homeworkAverage: 80,
    quizAverage: 75,
    examScore: 60,
    final: 68.5,
    display: '68.5',
    droppedHomework: null
  });
});

test('no quiz scores count as zero', function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] }), {
    homeworkAverage: 90,
    quizAverage: 0,
    examScore: 60,
    final: 48.0,
    display: '48.0',
    droppedHomework: 70
  });
});

test('final grade rounds to one decimal place and display always shows that decimal', function () {
  assert.deepEqual(code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] }), {
    homeworkAverage: (80 + 80 + 85) / 3,
    quizAverage: 70.5,
    examScore: 77,
    final: 76.0,
    display: '76.0',
    droppedHomework: null
  });
});

test('tied lowest homework score drops only one of them', function () {
  assert.deepEqual(code.finalGrade({ homework: [50, 50, 70, 90], quizzes: [80, 100], exam: [80] }), {
    homeworkAverage: 70,
    quizAverage: 90,
    examScore: 80,
    final: 81.0,
    display: '81.0',
    droppedHomework: 50
  });
});

test('quiz scores are averaged with no score dropped', function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70], quizzes: [50, 60, 70, 80], exam: [60] }), {
    homeworkAverage: 80,
    quizAverage: 65,
    examScore: 60,
    final: 65.5,
    display: '65.5',
    droppedHomework: null
  });
});

test('no homework scores count as zero', function () {
  assert.deepEqual(code.finalGrade({ homework: [], quizzes: [80, 70], exam: [60] }), {
    homeworkAverage: 0,
    quizAverage: 75,
    examScore: 60,
    final: 52.5,
    display: '52.5',
    droppedHomework: null
  });
});

test('no exam score counts as zero', function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [] }), {
    homeworkAverage: 90,
    quizAverage: 75,
    examScore: 0,
    final: 40.5,
    display: '40.5',
    droppedHomework: 70
  });
});
